// testKeyList builds a master key list from generated bytes, never from a literal key.
func testKeyList(version int) string {
	raw := make([]byte, 32)
	for i := range raw {
		raw[i] = byte(0x30 + i)
	}

	return string(rune('0'+version)) + ":" + base64.StdEncoding.EncodeToString(raw)
}

func newTestHandler(t *testing.T, cfg *config.Config, store confighandler.Store) confighandler.Handler {
	t.Helper()

	h, err := New(cfg, store)
	if err != nil {
		t.Fatalf("Wrong match. expect: ok, got: %v", err)
	}

	return h
}

func setSecret(t *testing.T, h confighandler.Handler, key, value string) {
	t.Helper()

	if _, err := h.SetSecret(context.Background(), uuid.Must(uuid.NewV4()), key, value); err != nil {
		t.Fatalf("Wrong match. expect: ok, got: %v", err)
	}
}

// The suppliers read the variable of the key at the time of use, trim it, and treat an unset,
// empty or unresolved placeholder value as not configured (an empty value, no error).
func Test_Supplier(t *testing.T) {
	tests := []struct {
		name string

		value string
		set   bool

		expect string
	}{
		{"unset", "", false, ""},
		{"empty", "", true, ""},
		{"spaces only", "  \t", true, ""},
		{"value", "fake-value", true, "fake-value"},
		{"value with surrounding space", " fake-value\n", true, "fake-value"},
		{"placeholder", "[[BIN_MANAGER__X]]", true, ""},
	}

	for _, key := range []string{configkeys.EnvPaddleAPIKey, configkeys.EnvPaddleWebhookSecret} {
		for _, tt := range tests {
			t.Run(key+" "+tt.name, func(t *testing.T) {
				if tt.set {
					t.Setenv(key, tt.value)
				} else {
					t.Setenv(key, "")
					_ = os.Unsetenv(key)
				}

				got, err := Supplier(key)(context.Background())
				if err != nil || got != tt.expect {
					t.Errorf("Wrong match. expect: %q, got: %q %v", tt.expect, got, err)
				}
			})
		}
	}
}

// The supplier keeps nothing: a changed variable is used by the next call.
func Test_Supplier_resolvedAtRequestTime(t *testing.T) {
	supplier := Supplier(configkeys.EnvPaddleWebhookSecret)

	for _, v := range []string{"fake-1", "fake-2", "", "fake-3"} {
		t.Setenv(configkeys.EnvPaddleWebhookSecret, v)
		if got, err := supplier(context.Background()); err != nil || got != v {
			t.Errorf("Wrong match. expect: %q, got: %q %v", v, got, err)
		}
	}
}

// failingStore fails the test when it is touched.
type failingStore struct {
	confighandler.Store
	t *testing.T
}

func (s failingStore) Get(ctx context.Context, key string) (*confighandler.Row, error) {
	s.t.Errorf("Wrong match. the stored settings were read: %s", key)
	return nil, errors.New("must not be called")
}

func (s failingStore) List(ctx context.Context) ([]*confighandler.Row, error) {
	s.t.Errorf("Wrong match. the stored settings were listed")
	return nil, errors.New("must not be called")
}

// The credentials come from the environment only: a stored value is never read, even when a store
// that fails when touched is wired next to the suppliers.
func Test_PaddleKeys_neverReadsTheStore(t *testing.T) {
	h := newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, failingStore{t: t})
	_ = h

	t.Setenv(configkeys.EnvPaddleAPIKey, "fake-api")
	t.Setenv(configkeys.EnvPaddleWebhookSecret, "fake-webhook")

	apiKey, webhookSecret := PaddleKeys()
	if v, err := apiKey(context.Background()); err != nil || v != "fake-api" {
		t.Errorf("Wrong match. expect: fake-api, got: %q %v", v, err)
	}
	if v, err := webhookSecret(context.Background()); err != nil || v != "fake-webhook" {
		t.Errorf("Wrong match. expect: fake-webhook, got: %q %v", v, err)
	}
	LogStates()
}

// A stored value is not the source: a stored secret next to an unset variable is not configured.
func Test_PaddleKeys_storedValueIsNotUsed(t *testing.T) {
	store := storetest.NewMemory()
	h := newTestHandler(t, &config.Config{ConfigEncryptionKeys: testKeyList(1)}, store)
	setSecret(t, h, configkeys.KeyPaddleAPIKey, "stored-value")
	setSecret(t, h, configkeys.KeyPaddleWebhookSecretKey, "stored-value")

	t.Setenv(configkeys.EnvPaddleAPIKey, "")
	t.Setenv(configkeys.EnvPaddleWebhookSecret, "")

	apiKey, webhookSecret := PaddleKeys()
	if v, err := apiKey(context.Background()); err != nil || v != "" {
		t.Errorf("Wrong match. expect: not configured, got: %q %v", v, err)
	}
	if v, err := webhookSecret(context.Background()); err != nil || v != "" {
		t.Errorf("Wrong match. expect: not configured, got: %q %v", v, err)
	}
}

// LogStates: the webhook secret that is not set is a warning (every webhook is rejected), the API
// key that is not set is an info line, a set variable is an info line, a placeholder is a warning
// that names the variable, and no line holds a value.
func Test_LogStates(t *testing.T) {
	levelOf := func(logs *logtest.Capture, name string) (logrus.Level, string) {
		for _, e := range logs.Entries() {
			if e.Data["variable"] == name {
				return e.Level, e.Message
			}
		}
		return logrus.PanicLevel, ""
	}

	t.Run("nothing set", func(t *testing.T) {
		t.Setenv(configkeys.EnvPaddleAPIKey, "")
		t.Setenv(configkeys.EnvPaddleWebhookSecret, "")
		logs := logtest.New(t)
		LogStates()

		if lvl, msg := levelOf(logs, configkeys.EnvPaddleWebhookSecret); lvl != logrus.WarnLevel || !strings.Contains(msg, "every Paddle webhook is rejected") {
			t.Errorf("Wrong match. expect: a warning that webhooks are rejected, got: %v %s", lvl, msg)
		}
		if lvl, _ := levelOf(logs, configkeys.EnvPaddleAPIKey); lvl != logrus.InfoLevel {
			t.Errorf("Wrong match. expect: an info line for the API key, got: %v", lvl)
		}
		if logs.HasLevel(logrus.ErrorLevel) {
			t.Errorf("Wrong match. expect: no error, got: %s", logs.Dump())
		}
	})

	t.Run("set", func(t *testing.T) {
		t.Setenv(configkeys.EnvPaddleAPIKey, "fake-api-text")
		t.Setenv(configkeys.EnvPaddleWebhookSecret, "fake-webhook-text")
		logs := logtest.New(t)
		LogStates()

		for _, e := range logs.Entries() {
			if e.Level != logrus.InfoLevel {
				t.Errorf("Wrong match. expect: info lines only, got: %v %s", e.Level, e.Message)
			}
		}
		if logs.Len() != 2 {
			t.Errorf("Wrong match. expect: one line per variable, got: %s", logs.Dump())
		}
		logs.AssertAbsent(t, "fake-api-text", "fake-webhook-text")
	})

	t.Run("placeholder", func(t *testing.T) {
		t.Setenv(configkeys.EnvPaddleAPIKey, "[[BIN_MANAGER__PADDLE_API_KEY]]")
		t.Setenv(configkeys.EnvPaddleWebhookSecret, "[[BIN_MANAGER__PADDLE_WEBHOOK_SECRET]]")
		logs := logtest.New(t)
		LogStates()

		for _, name := range []string{configkeys.EnvPaddleAPIKey, configkeys.EnvPaddleWebhookSecret} {
			lvl, msg := levelOf(logs, name)
			if lvl != logrus.WarnLevel || !strings.Contains(msg, "unresolved placeholder") || !strings.Contains(msg, name) {
				t.Errorf("Wrong match. %s: expect: a warning naming the variable, got: %v %s", name, lvl, msg)
			}
		}
		logs.AssertAbsent(t, "BIN_MANAGER__PADDLE")
	})
}

// A bad master key list never stops the service and is never printed.
func Test_New_badMasterKeyIsLoggedWithoutTheText(t *testing.T) {
	var buf bytes.Buffer
	prev := logrus.StandardLogger().Out
	logrus.SetOutput(&buf)
	defer logrus.SetOutput(prev)

	h := newTestHandler(t, &config.Config{ConfigEncryptionKeys: "7:unlikely-to-appear-in-logs"}, storetest.NewMemory())

	if _, err := h.SetSecret(context.Background(), uuid.Must(uuid.NewV4()), configkeys.KeyPaddleAPIKey, "x"); !errors.Is(err, confighandler.ErrKeyNotConfigured) {
		t.Errorf("Wrong match. expect: key not configured, got: %v", err)
	}
	if !strings.Contains(buf.String(), config.EnvConfigEncryptionKeys) {
		t.Errorf("Wrong match. expect: the problem to be logged, got: %q", buf.String())
	}
	if strings.Contains(buf.String(), "unlikely-to-appear-in-logs") {
		t.Errorf("Wrong match. the key list text was logged")
	}
}

// Without a master key list the handler is created without an error, a secret can not be
// stored, and an empty list is not reported as an error.
func Test_New_noMasterKey(t *testing.T) {
	logs := logtest.New(t)

	h := newTestHandler(t, &config.Config{}, storetest.NewMemory())

	if _, err := h.SetSecret(context.Background(), uuid.Must(uuid.NewV4()), configkeys.KeyPaddleWebhookSecretKey, "x"); !errors.Is(err, confighandler.ErrKeyNotConfigured) {
		t.Errorf("Wrong match. expect: key not configured, got: %v", err)
	}
	if strings.Contains(logs.Dump(), config.EnvConfigEncryptionKeys) {
		t.Errorf("Wrong match. an empty master key list must not be reported: %s", logs.Dump())
	}
}
